import type { Block, Post } from "./posts";
import { deepResearch } from "./deep-research";

type BlogSpec = {
  slug: string;
  title: string;
  tag: string;
  excerpt: string;
  keywords: string[];
  answer: string;
  sections: { heading: string; body: string; bullets: string[] }[];
  takeaway: string;
  faq: [string, string][];
  related: string[];
  source?: { label: string; href: string };
};

const p = (c: string): Block => ({ t: "p", c });
const h = (c: string): Block => ({ t: "h2", c });
const ul = (c: string[]): Block => ({ t: "ul", c });
const quote = (c: string): Block => ({ t: "quote", c });
const faq = (q: string, a: string): Block => ({ t: "faq", q, a });
const links = (items: { label: string; href: string }[]): Block => ({ t: "links", items });

const sharedLinks = (related: string[], source?: { label: string; href: string }) =>
  links([
    { label: "Read the MCP observability guide", href: "/blog/mcp-observability-guide" },
    { label: "Compare production observability tools", href: "/blog/best-mcp-observability-tools-for-production-servers" },
    { label: "Open TrackMCP documentation", href: "/docs" },
    ...related.map((slug) => ({ label: slug.replaceAll("-", " "), href: `/blog/${slug}` })),
    ...(source ? [source] : []),
  ]);

const makePost = (spec: BlogSpec): Post => {
  const research = deepResearch[spec.slug];
  const body: Block[] = [
    p(spec.answer),
    quote(spec.takeaway),
  ];
  for (const section of spec.sections) {
    body.push(h(section.heading), p(section.body), ul(section.bullets));
  }
  if (research) {
    body.push(
      h("What the MCP ecosystem already provides"),
      p(research.context),
      p("These tools and projects are useful comparison points, not interchangeable endorsements. The relevant question is where each one observes, what it can prove, what it leaves outside its boundary, and how its data handling fits the server owner's operating model."),
      ul(research.tools),
    );
    for (const section of research.sections) {
      body.push(h(section.heading), p(section.body), ul(section.bullets));
    }
    body.push(
      h("Research sources and implementation references"),
      links(research.sources),
    );
  }
  body.push(
    h("A practical decision rule"),
    p("Start with the question you need to answer, then choose the smallest source of evidence that can answer it. Keep protocol, server, client, model, infrastructure, and business-outcome signals labeled separately. That makes an observability result useful without claiming visibility the system does not have."),
    h("Frequently asked questions"),
    ...(research?.faq ?? []).map(([q, a]) => faq(q, a)),
    ...spec.faq.map(([q, a]) => faq(q, a)),
    sharedLinks(spec.related, spec.source),
  );
  return {
    slug: spec.slug,
    title: spec.title,
    tag: spec.tag,
    excerpt: spec.excerpt,
    date: "Oct 29, 2026",
    read: "8 min read",
    keywords: spec.keywords,
    related: spec.related,
    body,
  };
};

